.var level1TilesFile = LoadBinary("assets/level1-tiles.bin")
.var level1MapFile = LoadBinary("assets/level1-tv-map.bin")
.var level1AccentFile = LoadBinary("assets/level1-accents.bin")
.var level1PerspectiveAccentFile0 = LoadBinary("assets/level1-perspective-accents.bin")
.var level1PerspectiveAccentFile1 = LoadBinary("assets/level1-perspective-middle-accents.bin")
.var level1PerspectiveAccentFile2 = LoadBinary("assets/level1-perspective-right-accents.bin")

terrainTiles:
    .fill level1TilesFile.getSize(), level1TilesFile.get(i)
terrainTilesEnd:
.assert "Every terrain tile contains eight bytes", terrainTilesEnd - terrainTiles, TERRAIN_TILE_COUNT * 8

terrainMapStart:
terrainMapRow0:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 0)
terrainMapRow1:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 128)
terrainMapRow2:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 256)
terrainMapRow3:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 384)
terrainMapRow4:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 512)
terrainMapRow5:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 640)
terrainMapRow6:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 768)
terrainMapRow7:
    .fill TERRAIN_MAP_WIDTH, level1MapFile.get(i + 896)
terrainMapEnd:
.assert "Terrain map contains eight 128-column rows", terrainMapEnd - terrainMapStart, TERRAIN_MAP_WIDTH * TERRAIN_MAP_HEIGHT

.align $100
// Offset = phase * 128 + world column; bit 0 is row 0. Set means yellow.
terrainAccentMap:
    .fill level1AccentFile.getSize(), level1AccentFile.get(i)
.assert "Accent table has four 128-column phases", * - terrainAccentMap, 512
.assert "Accent table is page aligned", <terrainAccentMap, 0

.align $100
terrainPerspectiveAccentMap:
    .fill level1PerspectiveAccentFile0.getSize(), level1PerspectiveAccentFile0.get(i)
.assert "Perspective region 0 has four 128-column phases", * - terrainPerspectiveAccentMap, 512
.assert "Perspective region 0 is page aligned", <terrainPerspectiveAccentMap, 0

.align $100
terrainPerspectiveMiddleAccentMap:
    .fill level1PerspectiveAccentFile1.getSize(), level1PerspectiveAccentFile1.get(i)
.assert "Perspective region 1 has four 128-column phases", * - terrainPerspectiveMiddleAccentMap, 512
.assert "Perspective region 1 is page aligned", <terrainPerspectiveMiddleAccentMap, 0

.align $100
terrainPerspectiveRightAccentMap:
    .fill level1PerspectiveAccentFile2.getSize(), level1PerspectiveAccentFile2.get(i)
.assert "Perspective region 2 has four 128-column phases", * - terrainPerspectiveRightAccentMap, 512
.assert "Perspective region 2 is page aligned", <terrainPerspectiveRightAccentMap, 0

terrainDataEnd:

.var TERRAIN_PERSPECTIVE_ACCENT_MAPS = List()
.eval TERRAIN_PERSPECTIVE_ACCENT_MAPS.add(terrainPerspectiveAccentMap)
.eval TERRAIN_PERSPECTIVE_ACCENT_MAPS.add(terrainPerspectiveMiddleAccentMap)
.eval TERRAIN_PERSPECTIVE_ACCENT_MAPS.add(terrainPerspectiveRightAccentMap)
.eval TERRAIN_PERSPECTIVE_ACCENT_MAPS.add(terrainAccentMap)
